
-- ============================================================
-- 3. 权限码表 (permission_metas.json)
-- ============================================================
CREATE TABLE `hp_permissions` (
  `id`          INT UNSIGNED    NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `enum_key`    VARCHAR(64)     NOT NULL COMMENT '枚举标识（对应前端 Permission 枚举名）',
  `code`        VARCHAR(64)     NOT NULL COMMENT '权限码',
  `group_id`    VARCHAR(64)     NOT NULL COMMENT '分组标识（稳定 ID，用于分组聚合）',
  `group_name`  VARCHAR(64)     NOT NULL COMMENT '分组显示名称（中文，用于前端展示）',
  `label`       VARCHAR(100)    NOT NULL COMMENT '权限显示名称',
  `description` VARCHAR(500)    NULL     COMMENT '权限描述',
  `type`        VARCHAR(10)     NOT NULL DEFAULT 'view' COMMENT '权限类型 view/edit',
  `route`       VARCHAR(255)    NULL     COMMENT '页面路由（仅 view）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_enum_key` (`enum_key`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_group_id` (`group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统权限码表';

-- 数据以数据库 hp_permissions 为唯一真源（初始快照固化在本脚本）
